/**
 * Quran vocabulary, generated by scripts/build-learn-data.mjs — never edited by hand.
 * Roots, lemmas and counts: Quranic Arabic Corpus. Forms, meanings, audio, ayat: Quran.com API v4.
 */
import data from '../data/vocabulary.json';

export type PartOfSpeech = 'noun' | 'verb' | 'adjective';

export type VocabExample = {
  key: string;          // "surah:ayah"
  wordIndex: number;    // index of this word in `words`
  ar: string;           // the full ayah (Uthmani)
  translation: string;  // Saheeh International
  words: string[];
};

export type VocabWord = {
  id: string;
  lemma: string;        // dictionary form (Corpus)
  root: string;         // root letters, space separated
  pos: PartOfSpeech;
  occurrences: number;  // times this lemma occurs in the Qur'an (Corpus)
  form: string;         // the word as it appears at `meaningAt`
  translit: string | null;
  meaning: string;      // Quran.com word-by-word meaning at `meaningAt`
  meaningAt: string;    // "surah:ayah:word"
  audio: string | null; // word recitation (Quran.com)
  examples: VocabExample[];
};

export const VOCAB: VocabWord[] = data.words as VocabWord[];
export const VOCAB_BY_ID: Record<string, VocabWord> = Object.fromEntries(VOCAB.map(w => [w.id, w]));
export const VOCAB_SOURCES = data.meta.sources;

export const POS_LABEL: Record<PartOfSpeech, string> = { noun: 'Noun', verb: 'Verb', adjective: 'Adjective' };

/** Where a word's meaning was taken from, e.g. "87:1". */
export const meaningVerse = (w: VocabWord) => w.meaningAt.split(':').slice(0, 2).join(':');
